html:
{% set print_style = frappe.db.get_single_value("Print Settings", "print_style") %}
{% set color = frappe.db.get_value("Print Style", print_style, "custom_color") %}
<style>
    .pf-color { color: {{ color }}; }
</style>

<div class="pf-font">

    {% if letter_head %}
    {{ letter_head }}
    {% endif %}

    <h1 class="pf-heading pf-color">{{ doc.doctype }}</h1>

    <table class="pf-font-size" style="width:100%; border-collapse:collapse; margin-top:10px;">
        <tbody>

        <tr>
            <td style="width:50%; vertical-align:top;">
                <strong class="pf-color">SUPPLIER DETAILS</strong><br><br>

                {% if doc.supplier_name %}
                <strong>{{ doc.supplier_name }}</strong><br>
                {% endif %}

                {% if doc.address_display %}
                {{ doc.address_display }}<br>
                {% endif %}

                {% if doc.contact_mobile %}
                Phone: {{ doc.contact_mobile }}<br>
                {% endif %}



                <strong>Number of Trucks:</strong> {{ doc.custom_trucks}}<br>


                {% if doc.custom_dispatch_through %}
                Dispatch Through: {{ doc.custom_dispatch_through }}<br>
                {% endif %}


                {% if doc.bill_no %}
                <strong>Supplier SO No:</strong> {{ doc.bill_no }}<br>
                {% endif %}

                {% if doc.bill_date %}
                <strong>Supplier SO Date:</strong> {{ doc.bill_date }}<br>
                {% endif %}

            </td>

            <td style="width:50%; vertical-align:top; text-align:right;">

                <strong>Invoice #</strong><br>
                {{ doc.name }}<br><br>

                <strong>Purchase Date</strong><br>
                {{ doc.get_formatted("posting_date") }}<br><br>

                {% if doc.due_date %}
                <strong>Due Date</strong><br>
                {{ doc.get_formatted("due_date") }}<br><br>
                {% endif %}

                {% if doc.payment_terms_template %}
                <strong>Payment Terms</strong><br>
                {{ doc.payment_terms_template }}
                {% endif %}

            </td>
        </tr>

        </tbody>
    </table>
    


    <!-- ================= LCV LOOKUP (used by items table + charges table + totals) ================= -->

    {% set lcv_names = [] %}

    {# 1) LCV linked directly to this Purchase Invoice #}
    {% set lcv_from_pi = frappe.get_all(
        "Landed Cost Item",
        filters={
            "receipt_document_type": "Purchase Invoice",
            "receipt_document": doc.name
        },
        fields=["parent"]
    ) %}
    {% for r in lcv_from_pi %}
        {% if r.parent and r.parent not in lcv_names %}
            {% set _ = lcv_names.append(r.parent) %}
        {% endif %}
    {% endfor %}

    {# 2) LCV linked via Purchase Receipt (if PI has PRs) #}
    {% set pr_list = [] %}
    {% for it in doc.items %}
        {% if it.purchase_receipt and it.purchase_receipt not in pr_list %}
            {% set _ = pr_list.append(it.purchase_receipt) %}
        {% endif %}
    {% endfor %}

    {% if pr_list %}
        {% set lcv_links = frappe.get_all(
            "Landed Cost Purchase Receipt",
            filters={"receipt_document": ["in", pr_list]},
            fields=["parent"]
        ) %}
        {% for r in lcv_links %}
            {% if r.parent and r.parent not in lcv_names %}
                {% set _ = lcv_names.append(r.parent) %}
            {% endif %}
        {% endfor %}
    {% endif %}

    {# Only submitted LCVs count towards allocation / charges #}
    {% set submitted_lcvs = [] %}
    {% for lcv_name in lcv_names %}
        {% set lcv_doc = frappe.get_doc("Landed Cost Voucher", lcv_name) %}
        {% if lcv_doc.docstatus == 1 %}
            {% set _ = submitted_lcvs.append(lcv_doc) %}
        {% endif %}
    {% endfor %}


    {% set lcv_total_ns = namespace(company_amount=0) %}
    {% for lcv_doc in submitted_lcvs %}
        {% set lcv_total_ns.company_amount = lcv_total_ns.company_amount + (lcv_doc.total_taxes_and_charges or 0) %}
    {% endfor %}


    <!-- ================= ITEMS ================= -->
    <table class="pf-item-table pf-font-size" style="border:3px solid {{ color }}; margin-top:15px;">
        <thead>
        <tr style="background-color: {{ color }};">
            <th style="width:5%;">No</th>
            <th style="width:35%;">Item</th>
            <th style="width:15%;">Qty</th>
            <th style="width:20%;">Purchase Rate</th>
            <th style="width:20%;">Rate (After LCV)</th>
            <th style="width:25%;">Amount</th>
        </tr>
        </thead>
        <tbody>
        {% for item in doc.items %}

        {% set item_charge_ns = namespace(total=0) %}
        {% for lcv_doc in submitted_lcvs %}
            {% for lci in lcv_doc.items %}
                {% if lci.purchase_receipt_item == item.pr_detail %}
                    {% set item_charge_ns.total = item_charge_ns.total + (lci.applicable_charges or 0) %}
                {% endif %}
            {% endfor %}
        {% endfor %}

        <!--{% set received_stock_qty = (item.received_qty or item.qty) * (item.conversion_factor or 1) %}-->
        <!--{% set base_rate_per_stock_unit = (item.base_rate / item.conversion_factor) if item.conversion_factor else item.base_rate %}-->
        <!--{% set lcv_charge_per_stock_unit = (item_charge_ns.total / received_stock_qty) if received_stock_qty else 0 %}-->
        <!--{% set rate_after_lcv = base_rate_per_stock_unit + lcv_charge_per_stock_unit %}-->
        
        {% set rate_after_lcv = frappe.db.get_value(
            "Purchase Receipt Item",
            item.pr_detail,
            "valuation_rate"
        ) or item.valuation_rate or item.base_rate %}
        <tr>
            <td>{{ item.idx }}</td>
            <td><strong>{{ item.item_name }}</strong></td>

            <td style="text-align:center;">{{ item.qty }} {{ item.uom }}</td>
            <td style="text-align:center;">{{ item.get_formatted("rate", doc) }}</td>

            <td style="text-align:center;">
                {{ frappe.format_value(rate_after_lcv, {"fieldtype":"Currency"}, currency=doc.company_currency) }}
            </td>
            <td style="text-align:center;">{{ item.get_formatted("amount", doc) }}</td>
        </tr>
        {% endfor %}
        </tbody>
    </table>
    
    {% if doc.total_qty_by_uom %}
        <div  style="text-align:left; margin-top:5px; font-size: 12px;">
            <strong>Total Qty:</strong> {{ doc.total_qty_by_uom }}
        </div>
    {% endif %}

    <!-- ================= TAXES & CHARGES (PI + LCV) ================= -->

    {% if doc.taxes or submitted_lcvs %}

    <table class="pf-item-table pf-font-size" style="border:3px solid {{ color }}; margin-top:15px;">
        <thead>
            <tr style="background-color: {{ color }};">
                <th style="width:40%;">Account Name</th>
                <th style="width:35%;">Description</th>
                <th style="width:25%;">Amount</th>
            </tr>
        </thead>
        <tbody>

        <!-- Purchase Invoice Taxes -->
        {% for tax in doc.taxes %}
        <tr>
            <td>{{ tax.account_head }}</td>
            <td>{{ tax.description or "" }}</td>
            <td style="text-align:center;">
                {{ tax.get_formatted("tax_amount") }}
            </td>
        </tr>
        {% endfor %}

        <!-- LCV Charges (Submitted LCV only) — always in company currency (QAR) -->
        {% for lcv_doc in submitted_lcvs %}
            {% for t in lcv_doc.taxes %}
            <tr>
                <td>{{ t.expense_account }}</td>
                <td>{{ t.description or "" }}</td>
                <td style="text-align:center;">
                    {{ frappe.format_value(t.base_amount, {"fieldtype":"Currency"}, currency=doc.company_currency) }}
                </td>
            </tr>
            {% endfor %}
        {% endfor %}

        </tbody>
    </table>

    {% endif %}

    <!-- ==== TOTALS ================= -->

    {% set is_multi_currency = doc.currency != doc.company_currency %}
    {% set conv_rate = doc.conversion_rate or 1 %}

    {% set purchase_amount_base = doc.base_total %}
    {% set purchase_amount_doc = doc.total %}
    {% set lcv_charges_base = lcv_total_ns.company_amount %}
    {% set lcv_charges_doc = lcv_charges_base / conv_rate %}
    {% set net_total_base = purchase_amount_base + lcv_charges_base %}
    {% set net_total_doc = purchase_amount_doc + lcv_charges_doc %}

    <div class="pf-font-size" style="display:flex; margin-top:20px; gap:20px;">

        <!-- LEFT: Company currency (QAR) -->
        <div style="flex:1;">
            <div style="display:flex; justify-content:space-between;">
                <div>Purchase Amount ({{ doc.company_currency }})</div>
                <div>{{ frappe.format_value(purchase_amount_base, {"fieldtype":"Currency"}, currency=doc.company_currency) }}</div>
            </div>
            <div style="display:flex; justify-content:space-between;">
                <div>LCV Charges ({{ doc.company_currency }})</div>
                <div>{{ frappe.format_value(lcv_charges_base, {"fieldtype":"Currency"}, currency=doc.company_currency) }}</div>
            </div>
            <div style="display:flex; justify-content:space-between;">
                <div>Grand Total ({{ doc.company_currency }})</div>
                <div>{{ doc.get_formatted("base_grand_total") }}</div>
            </div>
            <div style="display:flex; justify-content:space-between;">
                <div><strong class="pf-color">Net Total ({{ doc.company_currency }})</strong></div>
                <div><strong>{{ frappe.format_value(net_total_base, {"fieldtype":"Currency"}, currency=doc.company_currency) }}</strong></div>
            </div>
        </div>

        {% if is_multi_currency %}
        <div style="flex:1;">
            <div style="display:flex; justify-content:space-between;">
                <div>Purchase Amount ({{ doc.currency }})</div>
                <div>{{ frappe.format_value(purchase_amount_doc, {"fieldtype":"Currency"}, currency=doc.currency) }}</div>
            </div>
            <div style="display:flex; justify-content:space-between;">
                <div>LCV Charges ({{ doc.currency }})</div>
                <div>{{ frappe.format_value(lcv_charges_doc, {"fieldtype":"Currency"}, currency=doc.currency) }}</div>
            </div>
            <div style="display:flex; justify-content:space-between;">
                <div>Grand Total ({{ doc.currency }})</div>
                <div>{{ doc.get_formatted("grand_total") }}</div>
            </div>
            <div style="display:flex; justify-content:space-between;">
                <div><strong class="pf-color">Net Total ({{ doc.currency }})</strong></div>
                <div><strong>{{ frappe.format_value(net_total_doc, {"fieldtype":"Currency"}, currency=doc.currency) }}</strong></div>
            </div>
        </div>
        {% endif %}

    </div>

    <div class="pf-font-size" style="text-align:center; margin-top:10px;">
        In Words: <strong>{{ doc.base_in_words }}</strong>
    </div>


    <!-- ================= REMARKS ================= -->
    {% if doc.remarks %}
    <div style="margin-top:20px;">
        <strong class="pf-color">Remarks</strong>
        <p>{{ doc.remarks }}</p>
    </div>
    {% endif %}

    {% if footer %}
    <div class="text-center footer small">
        {{ footer }}
    </div>
    {% endif %}

</div>
